/// <summary>
/// This is an event handler class for the SysDocuBrandDetails Form.
/// </summary>
internal final class METSysDocuBrandDetailsFormEventHandler
{
}

Method.Source:
    /// <summary>
    /// This is an event for Report name control to make Industry key field mandatory based on the  value selection.
    /// </summary>
    /// <param name="sender">Sender</param>
    /// <param name="e">Event</param>
    [FormControlEventHandler(formControlStr(SysDocuBrandDetails, Overview_ReportName), FormControlEventType::Modified)]
    public static void Overview_ReportName_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormStringControl  industryKey = sender.formRun().design(1).controlName(formControlStr(SysDocuBrandDetails, Overview_METIndustryKey));

        if (sender.valueStr())
        {
            industryKey.mandatory(true);
        }
        else
        {
            industryKey.mandatory(false);
        }
        
    }

    /// <summary>
    /// Increase the number of columns to 5 on the overview group.
    /// </summary>
    /// <param name="args">Form args.</param>
    [PostHandlerFor(formStr(SysDocuBrandDetails), formMethodStr(SysDocuBrandDetails, init))]
    public static void SysDocuBrandDetails_Post_init(XppPrePostArgs args)
    {
        FormRun formRun =  args.getThis();
        FormGroupControl  overview = formRun.design(1).controlName(formControlStr(SysDocuBrandDetails, Overview));

        overview.columnsMode(ColumnsMode::Fixed);
        overview.columns(5);

    }
